#include <bits/stdc++.h>using namespace std; int main() {     int t;    cin >> t;     while (t--) {        int n, k;        cin >> n >> k;         vector<int>a(n);        for (int &x : a) cin >> x;         int ans = 1e9;         if (k == 2) {            bool even = false;            for (int x : a)                if (x % 2 == 0) even = true;             ans = even ? 0 : 1;        }         else if (k == 3) {            for (int x : a)                ans = min(ans, (3 - x % 3) % 3);        }         else if (k == 5) {            for (int x : a)                ans = min(ans, (5 - x % 5) % 5);        }         else if (k == 4) {             int even = 0;            for (int x : a)                if (x % 2 == 0) even++;             int optionB;             if (even >= 2) optionB = 0;            else if (even == 1) optionB = 1;            else optionB = 2;             int optionA = 1e9;            for (int x : a)                optionA = min(optionA, (4 - x % 4) % 4);             ans = min(optionA, optionB);        }         cout << ans << "\n";    }}